/* TADAZZ / Studio: editorial dark interface with stage-light accents.
   One clear lime action. Stage energy lives in imagery, not form chrome. */
:host{
  --bg:#0c071d; --bg2:#120921; --side:#0e081e; --panel:#1d112e;
  --panel2:#28163e; --muted:#b2a5c4; --subtle:#8e809f;
  --text:#faf8ff; --lime:#e5ff39; --violet:#a25ffb;
  --line:rgba(215,186,248,.11); --line2:rgba(216,161,248,.19);
  --shadow:0 20px 55px rgba(4,0,17,.22);
  --font:Inter,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;
}
html,body{scroll-behavior:smooth}
body{font-size:14px;line-height:1.55;letter-spacing:-.006em;background:#0a0618}
.eyebrow,.side-label,.side-tip,.side-sep,.demo-disclaimer:empty{display:none!important}
.muted{color:var(--muted)}
.btn{min-height:44px;padding:11px 19px;border-radius:12px;font-size:12px;font-weight:740;letter-spacing:-.012em;box-shadow:none!important;transition:background .2s ease,color .2s ease,transform .2s ease,border-color .2s ease}
.btn:hover{transform:translateY(-1px)}
.btn.primary{background:var(--lime);border-color:var(--lime);color:#130b21;box-shadow:0 4px 28px rgba(229,255,55,.08)!important}
.btn.primary:hover{background:#f1ff7a;box-shadow:0 7px 24px rgba(229,255,55,.18)!important}
.btn.ghost{background:rgba(255,255,255,.035);color:#f3e9ff;border-color:rgba(201,158,248,.27)}
.btn.ghost:hover{background:rgba(255,255,255,.075);border-color:#9775bb}
.btn.quiet{background:transparent;border-color:rgba(201,158,248,.18)}
.btn.sm{font-size:12px;min-height:36px;border-radius:10px}
.text-link{font-weight:550;font-size:13px;display:inline-flex;align-items:center;gap:7px;color:#c7b9d9}
.text-link:hover{color:#f7f0ff}
.text-link .i{transition:transform .2s}
.text-link:hover .i{transform:translateX(3px)}
/* Sidebar is a quiet stage wing, not a glowing navigation template. */
.sidebar{width:246px;background:linear-gradient(168deg,#1c0f2b 0%,#110a20 33%,#0b0719 82%);border-right:1px solid rgba(201,166,230,.105);overflow:hidden}
.sidebar:after{content:"";position:absolute;width:550px;height:420px;left:-320px;bottom:-320px;pointer-events:none;border:1px solid rgba(122,67,241,.38);border-radius:50%;transform:rotate(-31deg);box-shadow:0 -9px 80px rgba(96,35,227,.21),0 -28px 95px rgba(223,44,236,.14)}
.side-brand{padding:19px 27px;height:123px;justify-content:flex-start}
.side-brand img{width:151px;max-height:72px;filter:none;transition:filter .2s}
.side-brand:hover img{filter:drop-shadow(0 0 12px rgba(217,80,244,.28))}
.side-nav{padding:17px 18px 0;gap:7px;display:grid}
.nav-btn{border-radius:9px;background:none;min-height:48px;padding:0 12px;font-size:13.5px;font-weight:530;color:#a99dbb;gap:15px;position:relative}
.nav-btn svg{opacity:.86;width:20px;height:20px}
.nav-btn.active,.nav-btn:hover:not(.active){background:transparent;border:0;box-shadow:none}
.nav-btn.active{color:#fff;font-weight:760}
.nav-btn.active svg{color:#d7ff62;opacity:1}
.nav-btn:hover{color:#fff!important}
.nav-btn:before{content:"";position:absolute;left:0;right:0;top:2px;bottom:2px;border-radius:9px;background:rgba(255,255,255,.035);opacity:0;transition:opacity .2s;pointer-events:none}
.nav-btn:hover:before{opacity:1}
.nav-btn.active:before{opacity:0}
.side-bottom{margin-top:auto;padding:20px 23px 24px;position:relative;z-index:2}
.side-account{padding:16px 1px 0;border-top:1px solid rgba(223,192,251,.105);gap:11px;color:#e6dcf3}
.side-account .who{font-weight:560;font-size:12px}
.side-account .avatar,.avatar{background:#e5ff39;color:#100921;border-radius:50%;width:33px;height:33px;font-size:10px;letter-spacing:-.03em}
.side-account .i{width:15px;height:15px;color:#a58fb8}
/* Layout */
.main{margin-left:246px;width:calc(100% - 246px);background:radial-gradient(ellipse 850px 450px at 70% -200px,rgba(115,46,174,.12),transparent 80%),linear-gradient(165deg,#140b26 0%,#0d071c 49%,#0a0618 100%)}
.topbar{height:84px;padding:0 clamp(24px,3vw,48px);background:rgba(14,8,29,.86);border-bottom:1px solid rgba(222,183,255,.075);backdrop-filter:blur(22px)}
.top-left{font-size:14px;font-weight:630;color:#f8f4ff;letter-spacing:-.02em}
.top-left strong{font-weight:690}
.top-actions{gap:12px}
.search-mini{min-width:235px;padding:10px 16px;background:#20132f8c;border:1px solid rgba(211,156,249,.24);border-radius:22px;height:42px;transition:border-color .2s}
.search-mini:focus-within{border-color:#b18bd2}
.search-mini .i{color:#b9aacb}
.search-mini input{font-size:12px;width:170px}
.search-mini input::placeholder{color:#9e90b3}
.circle-btn{border-radius:12px;background:rgba(255,255,255,.035);border:1px solid rgba(207,159,247,.17);color:#c8b6de;width:41px;height:41px}
.circle-btn:hover{background:#2d1a3f;border-color:#9470ba}
.top-actions .btn.primary{padding:0 19px;min-height:42px;font-size:12px;border-radius:12px}
.top-avatar{padding:0 0 0 8px;display:flex;gap:7px;align-items:center;background:transparent;color:#a493ba}
.top-avatar .avatar{width:38px;height:38px;font-size:10px;border:2px solid #121029;box-shadow:0 0 0 1px #d2bcfa25}
.top-avatar .i{width:15px;color:#9f8cad}
.content{width:min(1430px,100%);padding:34px clamp(24px,3vw,48px) 86px}
.page-enter{animation:studioRise .5s cubic-bezier(.16,1,.3,1) both}
@keyframes studioRise{from{opacity:0;transform:translateY(9px)}to{opacity:1;transform:translateY(0)}}
/* One theatrical hero, but legible and calm. */
.welcome{height:289px;min-height:289px;border-radius:26px;isolation:isolate;overflow:hidden;border:1px solid rgba(206,88,239,.31);background:radial-gradient(ellipse 400px 280px at 80% 87%,rgba(27,79,255,.29),transparent 80%),radial-gradient(ellipse 390px 290px at 91% 2%,rgba(142,21,234,.25),transparent 85%),linear-gradient(112deg,#281040 0%,#1c093b 54%,#250852 100%);box-shadow:inset 0 1px rgba(255,255,255,.06),0 18px 44px rgba(9,0,27,.21)}
.welcome:before{content:"";position:absolute;inset:0;z-index:0;pointer-events:none;background:radial-gradient(ellipse 380px 110px at 70% 109%,rgba(249,42,223,.41),transparent 77%),radial-gradient(ellipse 370px 200px at 98% 87%,rgba(19,164,255,.16),transparent 85%)}
.welcome:after{content:"";position:absolute;right:-70px;bottom:-120px;width:720px;height:210px;transform:rotate(-15deg);background:linear-gradient(0deg,transparent,rgba(30,27,228,.24) 43%,rgba(223,29,255,.2) 60%,transparent 85%);filter:blur(20px);border-radius:50%;pointer-events:none}
.hero-orbit{position:absolute;border-radius:50%;pointer-events:none;z-index:0}
.orbit-a{width:760px;height:380px;right:-205px;top:5px;border-top:2px solid rgba(255,51,223,.65);transform:rotate(-29deg);filter:drop-shadow(0 0 8px rgba(255,33,225,.66));opacity:.72}
.orbit-b{width:825px;height:320px;right:-282px;bottom:-250px;border-top:2px solid rgba(24,140,255,.81);transform:rotate(-17deg);filter:drop-shadow(0 0 8px rgba(47,136,255,.65));opacity:.72}
.welcome-copy{padding:58px clamp(34px,4.5vw,64px);z-index:3;max-width:67%;height:100%;display:flex;flex-direction:column;align-items:flex-start;justify-content:center}
.welcome-copy h1{margin:0 0 24px;font-size:clamp(46px,4.35vw,70px);line-height:1;letter-spacing:-.072em;font-weight:830;white-space:nowrap;text-shadow:0 4px 25px #13052040}
.welcome-copy h1 em{color:#e5ff3b;font-style:normal}
.hero-explore{position:relative;display:inline-flex;align-items:center;gap:13px;padding:9px 0;color:#f3e6fd;font-weight:690;font-size:13px;letter-spacing:-.01em;border-bottom:1px solid rgba(229,255,55,.62);transition:gap .2s,color .2s}
.hero-explore:hover{gap:19px;color:var(--lime)}
.hero-explore .i{color:#d7fc56}
.hero-mobile-create{display:none}
.welcome-art{width:460px;height:300px;right:clamp(-10px,1vw,18px);top:-3px;overflow:visible;z-index:2;filter:saturate(1.12)}
.welcome-art:before{content:"";position:absolute;left:0;right:0;bottom:-23px;height:78px;border-radius:50%;background:radial-gradient(ellipse,rgba(243,33,255,.4),rgba(71,49,251,.15) 43%,transparent 68%);filter:blur(12px)}
.welcome-art .blue,.welcome-art .lime{height:300px;width:auto;max-width:none;position:absolute;top:0;animation:none;will-change:transform;transform-origin:50% 80%}
.welcome-art .blue{left:56px;top:-3px;filter:drop-shadow(0 14px 13px #0b0080cc) drop-shadow(0 1px 19px #9c3ff97a);animation:zedInBlue 1.25s cubic-bezier(.12,.78,.22,1) both, floatBlue 8s 1.25s ease-in-out infinite}
.welcome-art .lime{left:190px;top:15px;height:286px;filter:drop-shadow(0 16px 14px #250332ad) drop-shadow(0 0 19px #d9e24555);animation:zedInLime 1.35s cubic-bezier(.12,.78,.22,1) both,floatLime 8s 1.35s ease-in-out infinite}
@keyframes zedInBlue{from{opacity:0;transform:translate(-56px,34px) rotate(-20deg) scale(.83)}to{opacity:1;transform:rotate(-7deg)}}
@keyframes zedInLime{from{opacity:0;transform:translate(65px,34px) rotate(23deg) scale(.83)}to{opacity:1;transform:rotate(8deg)}}
@keyframes floatBlue{50%{transform:translateY(-5px) rotate(-5deg)}}
@keyframes floatLime{50%{transform:translateY(6px) rotate(6deg)}}
/* Two actionable focus cards: strong imagery, zero eyebrow labels. */
.spotlight-grid{grid-template-columns:1fr 1fr;gap:20px;margin-top:22px}
.spotlight{min-height:169px;background:linear-gradient(115deg,#29133e,#211033);border-radius:19px;border:1px solid rgba(202,110,249,.16);padding:20px 23px;gap:20px;box-shadow:0 9px 25px #00000017;transition:transform .23s ease, border-color .23s ease;position:relative;isolation:isolate}
.spotlight:hover{transform:translateY(-3px);border-color:rgba(207,132,255,.36)}
.spotlight.upcoming{background:radial-gradient(ellipse 300px 180px at 100% 120%,rgba(177,30,216,.29),transparent 83%),linear-gradient(120deg,#301447,#1d1131)}
.spotlight.editing{background:radial-gradient(ellipse 330px 190px at 112% 80%,rgba(30,96,245,.27),transparent 80%),linear-gradient(110deg,#231338,#15102d)}
.spotlight:before{background:none}
.spotlight .thumb,.spotlight.compact .thumb{width:142px;height:113px;aspect-ratio:auto;border-radius:12px;overflow:hidden;background:#170b29;position:relative;flex:none}
.spotlight .thumb img{width:100%;height:100%;object-fit:cover}
.spotlight-info{display:flex;flex-direction:column;align-items:flex-start;justify-content:center;min-height:113px}
.spotlight-info h3,.spotlight.compact .spotlight-info h3{font-size:clamp(17px,1.65vw,23px);font-weight:740;letter-spacing:-.037em;margin:0 0 3px;line-height:1.16}
.spotlight-info p{color:#b5a4c8;font-size:11px;margin:3px 0 12px}
.spotlight .spotlight-action{display:inline-flex;align-items:center;gap:11px;padding:2px 0;color:#ecff75;font-size:12.5px;font-weight:710;white-space:nowrap;transition:gap .2s}
.spotlight .spotlight-action:hover{gap:17px}
.spotlight.editing .spotlight-action{color:#e9dafa}
.meta-divider{color:#806d96;padding:0 4px}
/* Artwork-centric gallery; titles below, not repeated over the image. */
.section{margin-top:38px}
.section-head{margin-bottom:17px;align-items:center}
.section-head h2{font-size:23px;letter-spacing:-.05em;font-weight:765}
.games-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}
.game-card{border:0;background:transparent;border-radius:19px;overflow:visible;transition:transform .24s ease;box-shadow:none}
.game-card:hover{transform:translateY(-4px);box-shadow:none;border:0}
.cover-link{border-radius:18px;display:block;overflow:hidden;border:1px solid rgba(234,195,255,.16);background:#1c0c2b;box-shadow:0 12px 28px rgba(0,0,0,.13);isolation:isolate;transition:border-color .2s,box-shadow .2s}
.game-card:hover .cover-link{border-color:rgba(209,167,255,.45);box-shadow:0 16px 34px #0005}
.cover{aspect-ratio:1.66;border-radius:17px;transition:transform .45s cubic-bezier(.2,.7,.2,1)}
.game-card:hover .cover{transform:scale(1.035)}
.cover:before{background:linear-gradient(0deg,rgba(10,3,20,.23),transparent 45%)}
.cover.worlds{background: url('data:image/webp;base64,') center /cover no-repeat}
.cover.quiz{background:url('data:image/webp;base64,') center /cover no-repeat}
.cover.story{background:radial-gradient(ellipse 70% 90% at 80% 80%,rgba(141,28,231,.54),transparent 72%),linear-gradient(130deg,#531087,#18062b)}
.cover.crowd{background:radial-gradient(ellipse at 75% 80%,#7726cf88,transparent 85%),linear-gradient(130deg,#3a0d6a,#130929)}
.cover.picture{background:linear-gradient(180deg,transparent,#31157450),url('data:image/webp;base64,') center /cover}
.cover.finale{background:radial-gradient(ellipse at 70% 90%,#292edb7a,transparent 85%),linear-gradient(130deg,#251058,#11051e)}
.cover-z{position:absolute;z-index:2;filter:drop-shadow(0 6px 14px rgba(18,0,45,.4));transition:transform .42s ease}
.cover-z.blue{width:39%;height:auto;top:5%;left:27%;transform:rotate(-6deg)}
.cover-z.lime{width:36%;height:auto;top:7%;left:47%;transform:rotate(9deg)}
.cover.story .cover-z.blue{left:25%}.cover.story .cover-z.lime{left:47%}
.cover.finale .cover-z.blue{width:33%;top:7%;left:29%}.cover.finale .cover-z.lime{width:33%;left:50%;top:10%}
.cover-glint{position:absolute;inset:auto -5% -40% -5%;height:75%;z-index:1;pointer-events:none;background:radial-gradient(ellipse at 45% 25%,rgba(238,40,228,.43),transparent 58%);filter:blur(13px)}
.cover-badge,.cover-label,.cover-logo{display:none!important}
.game-body{padding:13px 2px 0;background:transparent}
.game-title-row{align-items:flex-start;gap:8px}
.game-title-link{display:inline-block;padding:0;text-align:left}
.game-title,.game-title-link .game-title{margin:0;font-size:15px;line-height:1.3;font-weight:725;letter-spacing:-.03em;color:#fff}
.game-title-link:hover .game-title{color:var(--lime)}
.game-desc{font-size:11px;line-height:1.45;margin:4px 0 0;color:#a99bbd;display:flex;align-items:center;flex-wrap:wrap;gap:3px}
.status-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#9876bf;margin-right:3px}
.status-dot.is-ready{background:#daef5f}
.dots{color:#b8aaca;border-radius:8px;width:31px;height:31px;display:grid;place-items:center;flex:none}
.dots:hover{background:#fff1;color:#fff}
.dots .i{width:19px;height:19px}
.games-grid .game-card.new-card,.games-grid .new-card{border:1px dashed rgba(173,139,201,.34);border-radius:19px;background:rgba(224,169,255,.025);min-height:210px;display:flex;flex-direction:column;gap:11px;align-items:center;justify-content:center;color:#ceb8db;box-shadow:none}
.new-card .newicon{background:none;border:1px solid rgba(215,255,75,.32);border-radius:50%;color:var(--lime);width:47px;height:47px;display:grid;place-items:center}
.new-card h3{margin:0;font-size:13px;font-weight:600}
.new-card p{display:none}
/* Inner pages are much quieter than the dashboard's hero. */
.pagehead{margin:5px 0 27px;align-items:center}
.pagehead h1{font-size:clamp(32px,3vw,46px);font-weight:780;letter-spacing:-.06em;margin:0;line-height:1.08}
.pagehead p{margin-top:8px;color:#aa9bbf;font-size:13px}
.list-toolbar{margin-bottom:27px;gap:20px}
.tabset{gap:26px}
.tabset button{padding:12px 0 13px;border-radius:0;background:none;color:#a89ab8;font-size:12.5px}
.tabset button.active{color:#fff;border-bottom-color:var(--lime);font-weight:680}
.tabset button:hover:not(.active){color:#ddd0ee;background:none}
.searchfield,.search-mini{box-shadow:none}
.searchfield{border-radius:11px;background:rgba(255,255,255,.025);border:1px solid rgba(211,181,246,.17);padding:9px 13px}
.searchfield input{font-size:12px}
.store-pagehead{margin-bottom:21px}
.store-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:26px 22px}
.store-card .game-body{padding-top:15px}
.store-description{min-height:36px;margin:9px 0 15px;color:#ae9fbd;font-size:12px;line-height:1.55;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.store-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;border-top:1px solid rgba(219,168,255,.11);padding:12px 0 0;margin-top:3px}
.store-actions .open{font-size:12px;color:#cabbda;font-weight:600;padding:5px 0;display:flex;gap:8px;align-items:center}
.store-actions .use{color:#e5ff67;font-weight:670}
.store-actions .open:hover{color:#fff}
/* Event/account/preparation/check-out screens share a restraint-first system. */
.event-row{border-radius:17px;background:linear-gradient(120deg,#21122f,#1a1029);border:1px solid rgba(210,165,250,.17);padding:21px;margin:0 0 14px;gap:20px}
.event-row .thumb{width:138px;height:91px;flex:none;border-radius:10px;overflow:hidden}
.event-row .summary h3{font-size:19px;font-weight:740;letter-spacing:-.03em;margin:0 0 6px}
.event-row .summary p{font-size:12px;color:#ada0bd;margin:0}
.event-row .btn{white-space:nowrap}
.account-card{background:linear-gradient(145deg,#231334,#160e26);border-color:rgba(202,161,233,.16);border-radius:19px;max-width:750px;padding:28px}
.account-card h3{font-size:18px;font-weight:720;margin-bottom:17px}
.account-item{padding:17px 0;border-color:rgba(220,178,255,.1)}
.account-item strong{font-size:13px;font-weight:590}
.account-item small{display:none}
.pill{border:1px solid rgba(206,160,242,.23);background:rgba(207,157,246,.08);font-size:10px}
.breadcrumb{margin:0 0 20px;font-size:12px}
.prefight{gap:22px}
.prefight .editor-panel,.editor-panel{background:#1c102b;border:1px solid rgba(201,152,238,.17);border-radius:17px;padding:27px}
.editor-panel h3{font-size:18px;font-weight:740;letter-spacing:-.025em}
.check-row{border-color:rgba(219,173,247,.09)}
.check-row span strong{font-size:13px}
.check-row span small{font-size:11px}
.prep-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:24px}
.inline-demo{color:#9c8faf;font-size:11px}
.prefight .side{border-radius:17px;border:1px solid rgba(201,160,245,.17)}
.pay-grid{gap:22px}
.pay-summary{background:linear-gradient(130deg,#251638,#180f2a);border-color:rgba(212,171,250,.2);border-radius:17px;padding:27px}
.pay-summary h3{font-size:19px;letter-spacing:-.025em;margin:0 0 20px}
.pay-summary .pay-note{font-size:11px}
.pay-stepbar span{background:#3c2b4c}.pay-stepbar span.on{background:var(--lime)}
.capacity-grid button{background:rgba(255,255,255,.025);border:1px solid rgba(210,172,248,.21)}
.capacity-grid button.active,.tier-row.active{background:rgba(212,255,69,.08);border-color:var(--lime);box-shadow:inset 0 0 0 1px rgba(225,255,65,.22)}
.tier-row{border:1px solid rgba(210,172,248,.2);background:rgba(255,255,255,.025);border-radius:12px}
.demo-disclaimer{color:#8d819e;font-size:11px;margin-top:25px}
/* Dialogs and loading/preview controls inherit the new softness. */
.modal{background:#211330;border:1px solid rgba(210,167,242,.23);border-radius:20px;box-shadow:0 35px 110px #0200089e}
.modal .option-tile{border-color:rgba(219,163,250,.16);background:rgba(255,255,255,.025)}
.toast{border-radius:13px;background:#271938;border:1px solid rgba(227,255,85,.27);color:#f9f4ff}
/* Responsive: prioritise the content, hide ornament as space narrows. */
@media(max-width:1300px){
 .sidebar{width:218px}.main{margin-left:218px;width:calc(100% - 218px)}
 .side-brand{padding-left:24px}.side-brand img{width:144px}
 .spotlight{padding:16px;gap:14px}.spotlight .thumb,.spotlight.compact .thumb{width:121px;height:105px}
 .welcome-art{right:-45px;opacity:.88}.welcome-copy{padding-left:45px}
 .search-mini{min-width:198px}.search-mini input{width:132px}
}
@media(max-width:1060px){
 .spotlight-grid{grid-template-columns:1fr 1fr;gap:13px}
 .spotlight .thumb,.spotlight.compact .thumb{width:95px;height:88px}
 .spotlight{gap:12px;padding:14px;min-height:140px}
 .spotlight-info h3,.spotlight.compact .spotlight-info h3{font-size:17px}
 .spotlight-info p{font-size:10px}
 .welcome-art{right:-86px;opacity:.7}
 .welcome-copy{max-width:68%}
 .games-grid,.store-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:24px 17px}
 .search-mini{display:none}
 .pay-grid{grid-template-columns:1fr 260px}
}
@media(max-width:760px){
 .sidebar{width:257px;transform:translateX(-105%);z-index:60;box-shadow:0 0 70px #0009}
 .sidebar.open{transform:translateX(0)}
 .main{margin-left:0;width:100%}
 .topbar{height:68px;padding:0 19px}
 .top-actions{gap:8px}
 .top-actions .top-create{display:none}
 .top-avatar{padding-left:0}
 .top-left{font-size:14px}
 .content{padding:22px 18px 66px}
 .welcome{height:243px;min-height:243px;border-radius:21px}
 .welcome-copy{padding:32px;max-width:100%}
 .welcome-copy h1{font-size:clamp(41px,8vw,57px);margin-bottom:18px}
 .welcome-art{width:340px;height:220px;right:-107px;top:10px;opacity:.26}
 .welcome-art .blue{height:230px;left:25px}.welcome-art .lime{height:214px;left:143px}
 .hero-explore{color:#fff}
 .hero-mobile-create{display:inline-flex;margin-top:15px}
 .spotlight-grid{grid-template-columns:1fr;gap:13px;margin-top:16px}
 .spotlight{min-height:137px;padding:16px}
 .spotlight .thumb,.spotlight.compact .thumb{height:100px;width:136px}
 .spotlight-info h3,.spotlight.compact .spotlight-info h3{font-size:19px}
 .section{margin-top:29px}
 .section-head h2{font-size:21px}
 .games-grid,.store-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:21px 13px}
 .pagehead h1{font-size:34px}
 .pay-grid,.prefight{grid-template-columns:1fr}
 .pay-summary{position:static}
 .pagehead{gap:15px}
}
@media(max-width:520px){
 .topbar{padding:0 15px}
 .top-actions .help-btn{display:none}
 .top-left{font-size:13px}
 .top-avatar .avatar{width:33px;height:33px}
 .content{padding:18px 15px 50px}
 .welcome{height:242px;min-height:242px}
 .welcome-copy{padding:26px 22px}
 .welcome-copy h1{font-size:clamp(38px,10vw,49px);white-space:normal}
 .welcome-art{right:-135px;opacity:.2}
 .spotlight .thumb,.spotlight.compact .thumb{width:95px;height:87px}
 .spotlight-info h3,.spotlight.compact .spotlight-info h3{font-size:17px}
 .spotlight{min-height:118px;padding:13px;gap:13px}
 .spotlight-info{min-height:84px}
 .spotlight-info p{margin:1px 0 8px}
 .spotlight .spotlight-action{font-size:12px}
 .games-grid,.store-grid{grid-template-columns:1fr 1fr;gap:23px 11px}
 .game-body{padding-top:9px}
 .game-title{font-size:13px}
 .game-desc{font-size:10px}
 .games-grid .game-card.new-card,.games-grid .new-card{min-height:140px}
 .store-grid{grid-template-columns:1fr;gap:23px}
 .store-description{min-height:unset}
 .pagehead{align-items:flex-start;flex-wrap:wrap}
 .pagehead .btn{font-size:11px}
 .list-toolbar{flex-wrap:wrap;gap:12px}.searchfield{width:100%}
 .event-row{flex-wrap:wrap;align-items:flex-start}.event-row .summary{flex:1}.event-row .btn{width:100%}
 .editor-panel{padding:19px}
}
@media(prefers-reduced-motion:reduce){
 *,*:before,*:after{animation-duration:.001ms!important;animation-iteration-count:1!important;transition-duration:.001ms!important;scroll-behavior:auto!important}
}
/* Fine-tuning after visual QA */
.tabset{background:transparent!important;border:0!important;box-shadow:none!important;border-radius:0!important;display:flex;gap:22px;padding:0}
.tabset button{background:transparent!important;border:0!important;border-bottom:2px solid transparent!important;box-shadow:none!important;border-radius:0!important;padding:11px 0 13px!important}
.tabset button.active{border-bottom-color:var(--lime)!important;background:transparent!important;color:#fff!important}
.modal-options .option-tile:hover{background:rgba(255,255,255,.065)}
@media (max-width:1300px){.nav-btn{font-size:12.5px;gap:12px;padding:0 9px}}
@media (max-width:520px){
  .top-avatar .i{display:none}
  .games-section .games-grid{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;overscroll-behavior-inline:contain;padding:0 0 10px;margin-right:-15px;scrollbar-width:none}
  .games-section .games-grid::-webkit-scrollbar{display:none}
  .games-section .game-card{flex:0 0 min(73vw,285px);scroll-snap-align:start}
  .games-section .game-card.new-card{min-height:182px}
}
/* Each library cover has a recognizable format; not five copies of the ZZ motif. */
.cover.crowd{background:radial-gradient(ellipse at 50% 75%,rgba(59,41,247,.33),transparent 70%),url('data:image/webp;base64,') center /cover no-repeat}
.cover.crowd:before{background:linear-gradient(0deg,#0e042978,transparent 60%)}
.survey-sample{position:absolute;z-index:2;left:12%;right:12%;top:34%;height:43%;display:grid;grid-template-columns:repeat(5,1fr);gap:3%;transform:perspective(500px) rotateX(9deg);filter:drop-shadow(0 8px 15px rgba(0,0,0,.42))}
.survey-sample .vote-tile{position:relative;border-radius:6px;background:linear-gradient(150deg,rgba(165,82,241,.43),rgba(42,13,86,.78));border:1px solid rgba(225,201,255,.54);box-shadow:inset 0 0 13px rgba(221,110,255,.27),0 1px 9px rgba(192,94,239,.18)}
.survey-sample .vote-tile:before{content:"";position:absolute;left:21%;right:21%;top:25%;bottom:34%;border-radius:50%;background:radial-gradient(circle at 38% 28%,#d8a1fa,#8a35a4 65%,#292064);opacity:.75}
.survey-sample .vote-tile:after{content:"";position:absolute;left:21%;right:21%;bottom:16%;height:5%;border-radius:20px;background:rgba(229,204,255,.76)}
.survey-sample .vote-tile:nth-child(2){background:linear-gradient(150deg,rgba(38,184,255,.48),rgba(18,21,115,.8))}
.survey-sample .vote-tile:nth-child(3){background:linear-gradient(150deg,rgba(236,65,181,.5),rgba(80,15,83,.8))}
.survey-sample .vote-tile:nth-child(4){background:linear-gradient(150deg,rgba(93,128,255,.56),rgba(16,10,84,.85))}
.survey-sample .vote-tile:nth-child(5){background:linear-gradient(150deg,rgba(255,202,69,.43),rgba(86,39,21,.8))}
.cover.picture{background:radial-gradient(circle at 60% 100%,rgba(222,41,217,.27),transparent 65%),linear-gradient(140deg,#19103d,#31105f 60%,#160a27)}
.picture-sample{position:absolute;inset:0;z-index:2;display:flex;justify-content:center;align-items:center;gap:4%;transform:perspective(700px) rotate(-5deg)}
.picture-sample .pic-tile{display:block;width:25%;aspect-ratio:1;border-radius:10%;border:3px solid rgba(226,200,255,.76);box-shadow:0 15px 20px #0008,0 0 30px #b62cd555;transform:rotate(var(--rot));background:var(--c)}
.picture-sample .p1{--rot:-13deg;--c:radial-gradient(circle at 25% 23%,#f9a2ed 0,#af32ce 32%,#35128e 65%,#1a0741 100%);margin-top:10%}
.picture-sample .p2{--rot:4deg;--c:linear-gradient(145deg,#5febfe,#293ed8 48%,#0e1644 54%,#7234d5 100%);margin-top:-10%;z-index:2}
.picture-sample .p3{--rot:14deg;--c:radial-gradient(circle at 68% 32%,#edff6c,#6cbb5e 34%,#3d277d 75%,#170941);margin-top:7%}
.cover.finale{background:linear-gradient(0deg,rgba(17,3,42,.27),rgba(65,8,93,.3)),url('data:image/webp;base64,') 50% 64%/cover no-repeat}
.finale-sample{position:absolute;z-index:3;inset:0;display:grid;place-items:center;background:radial-gradient(ellipse at 50% 55%,rgba(84,23,168,.29),transparent 72%)}
.finale-sample img{width:60%;filter:drop-shadow(0 10px 12px rgba(18,0,42,.65))}
@media (max-width:520px){.survey-sample .vote-tile{border-radius:4px}.picture-sample .pic-tile{border-width:2px}}
